"""The ``record_*_metric`` functions the lifecycle recorders call.

Measurements are fire-and-forget and carry no per-operation state, so this
module is deliberately functions, not a class. The ``_metric`` suffix keeps
call sites inside the lifecycle recorders unambiguous next to their span
writes. Every function is a safe no-op until instruments are registered, so
call sites never need to check configuration. Functions construct metric
attributes internally — IDs, transcripts, model names, URLs, and exception
messages are never metric attributes. Free-form string parameters
(``provider``, ``reason``) must be short developer-controlled tokens, never
user content.
"""

from __future__ import annotations

from typing import Dict, Optional, Union

from opentelemetry.metrics import Counter, Histogram
from opentelemetry.util.types import AttributeValue

from rasa.tracing.voice.metrics.attribute_values import (
    AudioDirection,
    CallOutcome,
    InteractionOutcome,
    VoiceComponent,
    VoiceOperation,
)
from rasa.tracing.voice.metrics.instruments import get_registered_instrument
from rasa.tracing.voice.shared import semconv


def record_call_duration_metric(seconds: float, *, outcome: CallOutcome) -> None:
    """Record the total duration of an ended call.

    Args:
        seconds: Call duration in seconds.
        outcome: Terminal state of the call.
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_CALL_DURATION)
    if not isinstance(instrument, Histogram) or seconds < 0:
        return
    instrument.record(seconds, {semconv.METRIC_ATTR_OUTCOME: outcome.value})


def record_tts_time_to_first_audio_metric(
    seconds: float,
    *,
    provider: Optional[str] = None,
    cache_hit: Optional[bool] = None,
) -> None:
    """Record the latency from a synthesis request to its first audio chunk.

    Args:
        seconds: Seconds from the synthesis request to the first generated
            audio chunk.
        provider: Engine name as reported by ``TTSEngine.name()``.
        cache_hit: Whether the audio was served from the TTS cache.
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_TTS_TIME_TO_FIRST_AUDIO)
    if not isinstance(instrument, Histogram) or seconds < 0:
        return
    attributes: Dict[str, AttributeValue] = {}
    if provider is not None:
        attributes[semconv.METRIC_ATTR_PROVIDER] = provider
    if cache_hit is not None:
        attributes[semconv.METRIC_ATTR_TTS_CACHE_HIT] = cache_hit
    instrument.record(seconds, attributes)


def record_tts_synthesis_duration_metric(
    seconds: float,
    *,
    outcome: InteractionOutcome,
    provider: Optional[str] = None,
    cache_hit: Optional[bool] = None,
) -> None:
    """Record the duration from a synthesis request to its terminal state.

    Args:
        seconds: Seconds from the synthesis request to the terminal state.
        outcome: Terminal state of the synthesis (completed or error).
        provider: Engine name as reported by ``TTSEngine.name()``.
        cache_hit: Whether the audio was served from the TTS cache.
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_TTS_SYNTHESIS_DURATION)
    if not isinstance(instrument, Histogram) or seconds < 0:
        return
    attributes: Dict[str, AttributeValue] = {semconv.METRIC_ATTR_OUTCOME: outcome.value}
    if provider is not None:
        attributes[semconv.METRIC_ATTR_PROVIDER] = provider
    if cache_hit is not None:
        attributes[semconv.METRIC_ATTR_TTS_CACHE_HIT] = cache_hit
    instrument.record(seconds, attributes)


def record_playback_duration_metric(
    seconds: float, *, outcome: InteractionOutcome
) -> None:
    """Record the duration of one agent utterance's audio delivery.

    Args:
        seconds: Seconds from the first delivered chunk to the terminal
            playback state.
        outcome: Terminal state of the playback (completed, interrupted,
            cancelled, or error).
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_PLAYBACK_DURATION)
    if not isinstance(instrument, Histogram) or seconds < 0:
        return
    instrument.record(seconds, {semconv.METRIC_ATTR_OUTCOME: outcome.value})


def record_operation_failure_metric(
    *,
    component: VoiceComponent,
    operation: VoiceOperation,
    error: Union[BaseException, str],
    provider: Optional[str] = None,
) -> None:
    """Count an unexpected operational failure.

    Behavioral decisions (ignored barge-ins, DTMF timeouts) are not
    failures; count those with the ``record_*_decision_metric`` functions
    instead.

    Args:
        component: Pipeline stage where the failure occurred.
        operation: Operation that failed.
        error: The exception that caused the failure (its class name is
            recorded, never its message), or an explicit error-type token.
        provider: Engine name as reported by the ASR/TTS engine.
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_OPERATION_FAILURES)
    if not isinstance(instrument, Counter):
        return
    error_type = error if isinstance(error, str) else type(error).__name__
    attributes: Dict[str, AttributeValue] = {
        semconv.METRIC_ATTR_COMPONENT: component.value,
        semconv.METRIC_ATTR_OPERATION: operation.value,
        semconv.METRIC_ATTR_ERROR_TYPE: error_type,
    }
    if provider is not None:
        attributes[semconv.METRIC_ATTR_PROVIDER] = provider
    instrument.add(1, attributes)


def record_barge_in_decision_metric(
    *,
    outcome: InteractionOutcome,
    reason: Optional[str] = None,
) -> None:
    """Count an evaluated barge-in decision.

    Args:
        outcome: The classification verdict (accepted or ignored).
        reason: Decision reason token as emitted by the barge-in detector
            (a short constant, never user content).
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_BARGE_IN_DECISIONS)
    if not isinstance(instrument, Counter):
        return
    attributes: Dict[str, AttributeValue] = {semconv.METRIC_ATTR_OUTCOME: outcome.value}
    if reason is not None:
        attributes[semconv.METRIC_ATTR_REASON] = reason
    instrument.add(1, attributes)


def record_dtmf_decision_metric(
    *,
    outcome: InteractionOutcome,
    reason: Optional[str] = None,
) -> None:
    """Count an evaluated DTMF keypress decision.

    Args:
        outcome: The terminal decision (accepted, ignored, or timeout).
        reason: Decision reason token (a short constant, never a digit
            value or user content).
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_DTMF_DECISIONS)
    if not isinstance(instrument, Counter):
        return
    attributes: Dict[str, AttributeValue] = {semconv.METRIC_ATTR_OUTCOME: outcome.value}
    if reason is not None:
        attributes[semconv.METRIC_ATTR_REASON] = reason
    instrument.add(1, attributes)


def record_silence_timeout_metric(
    *,
    outcome: InteractionOutcome,
    timeout_s: Optional[float] = None,
) -> None:
    """Count a fired silence timeout.

    Args:
        outcome: The decision made for the fired timeout (accepted).
        timeout_s: Configured silence timeout that elapsed (a config
            value, not a runtime measurement).
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_SILENCE_TIMEOUTS)
    if not isinstance(instrument, Counter):
        return
    attributes: Dict[str, AttributeValue] = {semconv.METRIC_ATTR_OUTCOME: outcome.value}
    if timeout_s is not None:
        attributes[semconv.METRIC_ATTR_SILENCE_TIMEOUT_S] = round(float(timeout_s), 1)
    instrument.add(1, attributes)


def record_audio_bytes_metric(
    *,
    direction: AudioDirection,
    audio_bytes: int,
) -> None:
    """Count processed audio bytes.

    Args:
        direction: Whether the audio flowed into or out of the agent.
        audio_bytes: Number of audio bytes processed; non-positive values
            are skipped.
    """
    instrument = get_registered_instrument(semconv.METRIC_VOICE_AUDIO_BYTES)
    if isinstance(instrument, Counter) and audio_bytes > 0:
        instrument.add(
            audio_bytes, {semconv.METRIC_ATTR_AUDIO_DIRECTION: direction.value}
        )
